problems.solution:
Parametrii devin pointeri (`int *mn, int *mx`), funcția scrie prin ei (`*mn = ...`), iar `main` le trimite adresele (`&mn, &mx`).

```c
#include <stdio.h>

void minmax(int v[], int n, int *mn, int *mx) {
    *mn = *mx = v[0];
    for (int i = 1; i < n; i++) {
        if (v[i] < *mn) *mn = v[i];
        if (v[i] > *mx) *mx = v[i];
    }
}

int main(void) {
    int n, v[1000], mn = 0, mx = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &v[i]);
    minmax(v, n, &mn, &mx);
    printf("%d %d\n", mn, mx);
    return 0;
}
```

