problems.solution:
Verificarea e directă, poziție cu poziție. Atenție la citire: `scanf("%s")` s-ar opri la primul spațiu, de aceea se citește linia întreagă și se taie `\n`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int valid(const char *s) {
    if (strlen(s) != 8) return 0;
    if (!isupper((unsigned char)s[0])) return 0;
    if (!isupper((unsigned char)s[1]) && s[1] != ' ') return 0;
    if (!isdigit((unsigned char)s[2]) || !isdigit((unsigned char)s[3])) return 0;
    if (!isdigit((unsigned char)s[4]) && s[4] != ' ') return 0;
    for (int i = 5; i < 8; i++)
        if (!isupper((unsigned char)s[i])) return 0;
    return 1;
}

int main(void) {
    char line[64];
    int n;
    if (!fgets(line, sizeof line, stdin)) return 0;
    n = atoi(line);
    for (int k = 0; k < n; k++) {
        if (!fgets(line, sizeof line, stdin)) line[0] = '\0';
        line[strcspn(line, "\r\n")] = '\0';
        puts(valid(line) ? "DA" : "NU");
    }
    return 0;
}
```

