problems.solution:
Pentru fiecare cursă: `(st & 3) == 0` înseamnă nici anulată (bit 0), nici în desfășurare (bit 1); stelele sunt cei trei biți de la poziția 2. Ratingurile se compară exact, ca fracții.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n;
    char best[64] = "", name[64];
    long long bs = 0, bc = 1; /* best rating = bs / bc */
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        int k;
        long long s = 0, c = 0;
        scanf("%63s %d", name, &k);
        for (int j = 0; j < k; j++) {
            int st;
            scanf("%d", &st);
            if ((st & 3) == 0) {
                s += (st >> 2) & 7;
                c++;
            }
        }
        if (c == 0) { s = 0; c = 1; }
        if (i == 0 || s * bc > bs * c) {
            bs = s; bc = c;
            strcpy(best, name);
        }
    }
    printf("%s %.2f\n", best, (double)bs / bc);
    return 0;
}
```

