problems.solution:
Doar bitul 1 contează: `st & 2`. Parcurgerea identificatorilor în ordine crescătoare, cu `>` strict, alege la egalitate pe cel mai mic.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    static int cnt[10001];
    int m, best = 0;
    if (scanf("%d", &m) != 1) return 0;
    for (int i = 0; i < m; i++) {
        int st, id;
        scanf("%d %d", &st, &id);
        if (st & 2) cnt[id]++;
    }
    for (int id = 1; id <= 10000; id++)
        if (cnt[id] > cnt[best]) best = id;
    printf("%d %d\n", best, cnt[best]);
    return 0;
}
```

