problems.solution:
`qsort` cu o comparare pe două chei. Diferența a două `unsigned long long` nu încape într-un `int`, de aceea comparația se scrie cu `(a > b) - (a < b)`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned long long ts;
    char dest[256];
    char *text;
} TMesaj;

int cmp(const void *a, const void *b) {
    const TMesaj *x = (const TMesaj *)a, *y = (const TMesaj *)b;
    int c = strcmp(x->dest, y->dest);
    if (c) return c;
    return (x->ts > y->ts) - (x->ts < y->ts);
}

int main(void) {
    int n;
    char buf[1024];
    if (scanf("%d", &n) != 1) return 0;
    TMesaj *m = (TMesaj *)malloc(n * sizeof(TMesaj));
    for (int i = 0; i < n; i++) {
        scanf("%llu %255s %1023s", &m[i].ts, m[i].dest, buf);
        m[i].text = (char *)malloc(strlen(buf) + 1);
        strcpy(m[i].text, buf);
    }
    qsort(m, n, sizeof(TMesaj), cmp);
    for (int i = 0; i < n; i++) {
        printf("%s %llu %s\n", m[i].dest, m[i].ts, m[i].text);
        free(m[i].text);
    }
    free(m);
    return 0;
}
```

