problems.solution:
Se calculează pătratul distanței pentru fiecare șofer, apoi `qsort` cu o comparare care la egalitate trece la nume.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char nume[21];
    double x, y, d;
} TSofer;

int cmp(const void *a, const void *b) {
    const TSofer *p = (const TSofer *)a, *q = (const TSofer *)b;
    if (p->d < q->d) return -1;
    if (p->d > q->d) return 1;
    return strcmp(p->nume, q->nume);
}

int main(void) {
    int n, nr;
    double px, py;
    if (scanf("%d %d", &n, &nr) != 2) return 0;
    TSofer *s = (TSofer *)malloc(n * sizeof(TSofer));
    for (int i = 0; i < n; i++) scanf("%20s %lf %lf", s[i].nume, &s[i].x, &s[i].y);
    scanf("%lf %lf", &px, &py);
    for (int i = 0; i < n; i++)
        s[i].d = (s[i].x - px) * (s[i].x - px) + (s[i].y - py) * (s[i].y - py);
    qsort(s, n, sizeof(TSofer), cmp);
    for (int i = 0; i < nr; i++) puts(s[i].nume);
    free(s);
    return 0;
}
```

