problems.solution:
Exact ideea din subiect: câmpul `generator` al seriei e un pointer la funcție, iar `alocaSerie` alege funcția după primul octet al parametrilor. Atenție la Fibonacci: al 90-lea termen trece mult de `int`, de aceea `unsigned long long`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long long ull;
typedef ull *(*Generator)(unsigned r, unsigned a, unsigned n);

static int prim(ull x) {
    if (x < 2) return 0;
    for (ull d = 2; d * d <= x; d++)
        if (x % d == 0) return 0;
    return 1;
}

ull *prime(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    ull x = 1;
    for (unsigned i = 0; i < n; i++) {
        do x++; while (!prim(x));
        v[i] = x;
    }
    return v;
}

ull *fibo(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    for (unsigned i = 0; i < n; i++) v[i] = i < 2 ? 1 : v[i - 1] + v[i - 2];
    return v;
}

ull *arit(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    for (unsigned i = 0; i < n; i++) v[i] = i == 0 ? a : v[i - 1] + r;
    return v;
}

ull *geom(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    for (unsigned i = 0; i < n; i++) v[i] = i == 0 ? a : v[i - 1] * r;
    return v;
}

int main(void) {
    Generator gen[4] = {prime, fibo, arit, geom};
    unsigned t, n, r = 0, a = 0;
    if (scanf("%u %u", &t, &n) != 2) return 0;
    if (t >= 2) scanf("%u %u", &r, &a);
    ull *v = gen[t](r, a, n);
    for (unsigned i = 0; i < n; i++) printf("%llu%c", v[i], i + 1 < n ? ' ' : '\n');
    free(v);
    return 0;
