Intersecția a două șiruri sortate se face liniar, cu doi indici. După ultima serie, cel mai mare termen comun e ultimul element rămas. Funcția din subiect întorcea `unsigned long long`, cu -1 pentru „nu există” (adică cea mai mare valoare reprezentabilă); aici se afișează direct -1.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long long ull;

int main(void) {
    int k;
    if (scanf("%d", &k) != 1) return 0;
    int cm;
    scanf("%d", &cm);
    ull *cur = (ull *)malloc((cm + 1) * sizeof(ull));
    for (int i = 0; i < cm; i++) scanf("%llu", &cur[i]);
    for (int s = 1; s < k; s++) {
        int m, j = 0, nc = 0;
        scanf("%d", &m);
        ull *v = (ull *)malloc((m + 1) * sizeof(ull));
        for (int i = 0; i < m; i++) scanf("%llu", &v[i]);
        for (int i = 0; i < cm && j < m;) {
            if (cur[i] == v[j]) { cur[nc++] = cur[i]; i++; j++; }
            else if (cur[i] < v[j]) i++;
            else j++;
        }
        cm = nc;
        free(v);
    }
    if (cm == 0) puts("-1");
    else printf("%llu\n", cur[cm - 1]);
    free(cur);
    return 0;
}
