problems.solution:
Se păstrează doar tranzacțiile din anul cerut. După sortare, numele egale stau unul lângă altul; cel mai lung grup e răspunsul, iar la egalitate primul grup (cel mai mic alfabetic) rămâne, pentru că se compară cu `>` strict.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { char nume[31]; } TNume;

int cmp(const void *a, const void *b) { return strcmp(((const TNume *)a)->nume, ((const TNume *)b)->nume); }

int main(void) {
    int n, an, cnt = 0;
    if (scanf("%d %d", &n, &an) != 2) return 0;
    TNume *v = (TNume *)malloc(n * sizeof(TNume));
    for (int i = 0; i < n; i++) {
        char data[16], nume[31];
        double suma;
        scanf("%15s %30s %lf", data, nume, &suma);
        if (atoi(data + 6) == an) strcpy(v[cnt++].nume, nume);
    }
    if (cnt == 0) { puts("niciuna"); free(v); return 0; }
    qsort(v, cnt, sizeof(TNume), cmp);
    int best = 0, bestLen = 0;
    for (int i = 0; i < cnt;) {
        int j = i;
        while (j < cnt && strcmp(v[j].nume, v[i].nume) == 0) j++;
        if (j - i > bestLen) { bestLen = j - i; best = i; }
        i = j;
    }
    printf("%s %d\n", v[best].nume, bestLen);
    free(v);
    return 0;
}
